function linreg(xs, ys){
  var n=xs.length; if(n<2||n!==ys.length) return null;
  var mx=0,my=0,i; for(i=0;i<n;i++){mx+=xs[i];my+=ys[i];} mx/=n; my/=n;
  var sxy=0,sxx=0,syy=0; for(i=0;i<n;i++){var dx=xs[i]-mx,dy=ys[i]-my; sxy+=dx*dy; sxx+=dx*dx; syy+=dy*dy;}
  if(sxx===0) return null;
  var slope=sxy/sxx, intercept=my-slope*mx;
  var r2=(sxx===0||syy===0)?0:sxy*sxy/(sxx*syy);
  return {slope:slope, intercept:intercept, r2:r2, predict:function(x){return slope*x+intercept;}};
}
var EXPORTS={linreg:linreg};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
